_CORE_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Running cost: 3.0 * (trucks not on own base) +\n#               1.5 * (scooters not on own base), after movement.\n# Stock regenerates after service, rounded to two decimal places.\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\nTYPES = {"truck": (8, 3.0, 1), "scooter": (3, 1.5, 2)}\n\n\ndef payout(own, opponent, stock):\n    denominator = max(own + opponent, stock)\n    return own * stock / denominator if denominator > 0 else 0.0\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.dist = []\n        self.adj = []\n        self.targets = {}\n        self.bad_reports = 0\n\n    def _prepare_map(self, obs):\n        n = int(obs["n_nodes"])\n        key = (n, tuple(tuple(e) for e in obs["edges"]))\n        if key == self.map_key:\n            return\n        adj = [[] for _ in range(n)]\n        for a, b in obs["edges"]:\n            adj[a].append(b)\n            adj[b].append(a)\n        for row in adj:\n            row.sort()\n        distances = []\n        for source in range(n):\n            d = [n + 1] * n\n            d[source] = 0\n            queue = deque([source])\n            while queue:\n                u = queue.popleft()\n                for v in adj[u]:\n                    if d[v] > d[u] + 1:\n                        d[v] = d[u] + 1\n                        queue.append(v)\n            distances.append(d)\n        self.adj = adj\n        self.dist = distances\n        self.map_key = key\n        self.targets = {}\n\n    def _path(self, source, target, speed, horizon, stock):\n        # Choose shortest-path intermediate stops that can themselves serve orders.\n        path = []\n        current = source\n        n = len(self.dist)\n        for _ in range(horizon):\n            distance = self.dist[current][target]\n            if distance <= speed:\n                current = target\n            else:\n                options = [\n                    v for v in range(n)\n                    if self.dist[current][v] <= speed\n                    and self.dist[v][target] == distance - speed\n                ]\n                current = min(options, key=lambda v: (-stock[v], v))\n            path.append(current)\n        return path\n\n    def _legal_action(self, units, paths):\n        moves = {}\n        n = len(self.dist)\n        for uid in sorted(units):\n            kind, source = units[uid]\n            path = paths.get(uid)\n            if not path or kind not in TYPES:\n                continue\n            destination = int(path[0])\n            if (0 <= destination < n\n                    and self.dist[source][destination] <= TYPES[kind][2]\n                    and destination != source):\n                moves[str(uid)] = int(destination)\n        return {"moves": moves}\n\n    def _plan(self, obs, deadline):\n        units = obs.get("player_units", {})\n        n = int(obs["n_nodes"])\n        base = int(obs["player_base"])\n        stock = list(obs["stock"])\n        maximum = obs["stock_max"]\n        regen = obs["regen"]\n        remaining = max(1, N_TURNS - int(obs.get("turn", 0)))\n        horizon = min(6, remaining)\n        opponent = [0] * n\n        for kind, position in obs.get("opponent_units", {}).values():\n            if kind in TYPES:\n                opponent[position] += TYPES[kind][0]\n\n        # A complete, feasible baseline: retire each courier by a shortest route.\n        paths = {}\n        targets = {}\n        capacities = [[0] * n for _ in range(horizon)]\n        for uid in sorted(units):\n            kind, source = units[uid]\n            cap, cost, speed = TYPES[kind]\n            path = self._path(source, base, speed, horizon, stock)\n            paths[uid] = path\n            targets[uid] = base\n            for t, node in enumerate(path):\n                capacities[t][node] += cap\n\n        def node_value(node, changed=None, old_path=None, new_path=None, cap=0):\n            s = stock[node]\n            result = 0.0\n            enemy = opponent[node]\n            for t in range(horizon):\n                own = capacities[t][node]\n                if changed:\n                    if old_path[t] == node:\n                        own -= cap\n                    if new_path[t] == node:\n                        own += cap\n                our_service = payout(own, enemy, s)\n                enemy_service = payout(enemy, own, s)\n                result += our_service - enemy_service\n                s = round(min(maximum[node],\n                              s - our_service - enemy_service + regen[node]), 2)\n            return result\n\n        values = [node_value(v) for v in range(n)]\n\n        def path_cost(path, cost, speed):\n            running = sum(cost for v in path if v != base)\n            # Reserve a portion of the eventual retirement bill. This prevents\n            # short-horizon harvesting from ignoring the cost of returning home.\n            if remaining > horizon:\n                distance = self.dist[path[-1]][base]\n                running += 0.65 * cost * ((distance + speed - 1) // speed)\n            return running\n\n        def best_candidate(uid):\n            kind, source = units[uid]\n            cap, cost, speed = TYPES[kind]\n            old = paths[uid]\n            old_cost = path_cost(old, cost, speed)\n            best = (0.0, base, old)\n            for target in range(n):\n                if time.perf_counter() >= deadline:\n                    break\n                if target != base and maximum[target] <= 0:\n                    continue\n                path = self._path(source, target, speed, horizon, stock)\n                if path == old:\n                    continue\n                affected = sorted(set(old) | set(path))\n                gain = old_cost - path_cost(path, cost, speed)\n                for node in affected:\n                    gain += node_value(node, True, old, path, cap) - values[node]\n                # Small hysteresis only; it never justifies a clearly bad trip.\n                if target == self.targets.get(uid) and target != base:\n                    gain += 0.35\n                gain -= 0.15\n                if gain > best[0] + 1e-9:\n                    best = (gain, target, path)\n            return best\n\n        # Lazy marginal heap. Re-evaluate after each accepted allocation, since\n        # earlier couriers consume stock and alter both players\' future shares.\n        heap = []\n        revision = 0\n        for uid in sorted(units):\n            if time.perf_counter() >= deadline:\n                break\n            gain, target, path = best_candidate(uid)\n            heapq.heappush(heap, (-gain, uid, revision, target, path))\n\n        assigned = set()\n        while heap and time.perf_counter() < deadline:\n            neg_gain, uid, version, target, path = heapq.heappop(heap)\n            if uid in assigned:\n                continue\n            if version != revision:\n                gain, target, path = best_candidate(uid)\n                heapq.heappush(heap, (-gain, uid, revision, target, path))\n                continue\n            if neg_gain >= -1e-9:\n                break\n            cap = TYPES[units[uid][0]][0]\n            old = paths[uid]\n            affected = sorted(set(old) | set(path))\n            for t in range(horizon):\n                capacities[t][old[t]] -= cap\n                capacities[t][path[t]] += cap\n            paths[uid] = path\n            targets[uid] = target\n            for node in affected:\n                values[node] = node_value(node)\n            assigned.add(uid)\n            revision += 1\n\n        self.targets = targets\n        return paths\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        self._prepare_map(obs)\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n        units = obs.get("player_units", {})\n        if not units:\n            return {"moves": {}}\n        if self.bad_reports >= 2:\n            # Conservative recovery: only adjacent moves toward our base.\n            base = int(obs["player_base"])\n            paths = {}\n            for uid in sorted(units):\n                source = units[uid][1]\n                if source == base:\n                    paths[uid] = [base]\n                else:\n                    destination = min(\n                        self.adj[source],\n                        key=lambda v: (self.dist[v][base], v)\n                    )\n                    paths[uid] = [destination]\n            return self._legal_action(units, paths)\n        paths = self._plan(obs, deadline)\n        return self._legal_action(units, paths)\n'
_CORE_CLASS = 'Strategy'
